//! C ABI for the TPT Kinetix container tools.
//!
//! Exposed: [`tk_probe_json`] lists the tracks of a WebM, IVF or MP4 file as JSON,
//! [`tk_faststart`] writes a copy with the index moved to the front,
//! [`tk_remux`] copies the streams into another container without decoding, and
//! [`tk_package`] writes an HLS + DASH package to a directory. Plus the version and
//! error-string helpers. The header is `include/tpt_kinetix.h`, generated by
//! cbindgen (`just ffi-header`).
//!
//! Conventions: every string returned is owned by the caller and released with
//! [`tk_free_string`]; a function that fails returns null (or -1) and the reason
//! is available from [`tk_last_error`] on the same thread. No Rust panic crosses
//! the boundary.

use std::cell::RefCell;
use std::ffi::{c_char, c_int, CStr, CString};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::Path;

use tpt_kinetix_mux::Encryption;

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = const { RefCell::new(None) };
}

fn set_error(message: impl Into<String>) {
    let text = message.into().replace('\0', " ");
    LAST_ERROR.with(|e| *e.borrow_mut() = CString::new(text).ok());
}

/// Reads a caller's C string, or records an error and returns `None`.
///
/// # Safety
/// `ptr` must be null or point to a NUL-terminated string that stays valid for the call.
unsafe fn path_arg(ptr: *const c_char, what: &str) -> Option<String> {
    if ptr.is_null() {
        set_error(format!("{what} is null"));
        return None;
    }
    match CStr::from_ptr(ptr).to_str() {
        Ok(s) => Some(s.to_owned()),
        Err(_) => {
            set_error(format!("{what} is not valid UTF-8"));
            None
        }
    }
}

/// Reads an optional C string: null means `None`.
///
/// # Safety
/// Same contract as [`path_arg`] when `ptr` is not null.
unsafe fn opt_arg(ptr: *const c_char, what: &str) -> Result<Option<String>, String> {
    if ptr.is_null() {
        return Ok(None);
    }
    path_arg(ptr, what).map(Some).ok_or_else(|| {
        LAST_ERROR.with(|e| {
            e.borrow()
                .as_ref()
                .map(|m| m.to_string_lossy().into_owned())
                .unwrap_or_default()
        })
    })
}

/// The library version, e.g. `0.1.2`. The string is static: do not free it.
#[no_mangle]
pub extern "C" fn tk_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr() as *const c_char
}

/// The message of the last failed call on this thread, or null when there is none.
/// The pointer stays valid until the next call on this thread that fails.
#[no_mangle]
pub extern "C" fn tk_last_error() -> *const c_char {
    LAST_ERROR.with(|e| match e.borrow().as_ref() {
        Some(s) => s.as_ptr(),
        None => std::ptr::null(),
    })
}

/// Frees a string returned by this library. Null is accepted and ignored.
///
/// # Safety
/// `s` must be null or a pointer returned by [`tk_probe_json`] and not freed yet.
#[no_mangle]
pub unsafe extern "C" fn tk_free_string(s: *mut c_char) {
    if !s.is_null() {
        drop(CString::from_raw(s));
    }
}

/// Lists the tracks of the file at `path` as JSON, or returns null on error.
///
/// The document has a `format` string and a `streams` array; each stream has
/// `index`, `codec`, `type` (`video`, `audio` or `other`), and for video `width` and
/// `height`, for audio `channels` and `sample_rate`. Free the result with
/// [`tk_free_string`].
///
/// # Safety
/// `path` must be a NUL-terminated UTF-8 string.
#[no_mangle]
pub unsafe extern "C" fn tk_probe_json(path: *const c_char) -> *mut c_char {
    let result = catch_unwind(AssertUnwindSafe(|| -> Option<String> {
        let path = path_arg(path, "path")?;
        match tpt_kinetix_ops::summary::summary_json(Path::new(&path)) {
            Ok(json) => Some(json),
            Err(e) => {
                set_error(e);
                None
            }
        }
    }));
    match result {
        Ok(Some(json)) => CString::new(json).map_or(std::ptr::null_mut(), CString::into_raw),
        Ok(None) => std::ptr::null_mut(),
        Err(_) => {
            set_error("internal error (panic) while probing");
            std::ptr::null_mut()
        }
    }
}

/// Writes a copy of `input` to `output` with the index moved to the front.
/// Returns 0 on success and -1 on error.
///
/// # Safety
/// `input` and `output` must be NUL-terminated UTF-8 strings.
#[no_mangle]
pub unsafe extern "C" fn tk_faststart(input: *const c_char, output: *const c_char) -> c_int {
    let result = catch_unwind(AssertUnwindSafe(|| -> Result<(), String> {
        let input = path_arg(input, "input").ok_or("input is missing")?;
        let output = path_arg(output, "output").ok_or("output is missing")?;
        tpt_kinetix_ops::faststart_file(Path::new(&input), Path::new(&output))
            .map_err(|e| format!("{e:#}"))
    }));
    status(result, "faststart")
}

/// Copies the streams of `input` into a new file at `output` without decoding.
///
/// The output container follows the extension of `output`: `.webm` and `.mkv` write
/// WebM, anything else writes MP4. `faststart` moves the index to the front of an
/// MP4. `fragment_ms` greater than zero writes fragmented MP4 with that target
/// fragment length; pass zero for a progressive file. Returns 0 on success and -1 on
/// error.
///
/// # Safety
/// `input` and `output` must be NUL-terminated UTF-8 strings.
#[no_mangle]
pub unsafe extern "C" fn tk_remux(
    input: *const c_char,
    output: *const c_char,
    faststart: c_int,
    fragment_ms: u32,
) -> c_int {
    let result = catch_unwind(AssertUnwindSafe(|| -> Result<(), String> {
        let input = path_arg(input, "input").ok_or("input is missing")?;
        let output = path_arg(output, "output").ok_or("output is missing")?;
        let fragment_ms = (fragment_ms > 0).then_some(fragment_ms);
        tpt_kinetix_ops::remux::remux(&input, Path::new(&output), faststart != 0, fragment_ms)
            .map_err(|e| format!("{e:#}"))
    }));
    status(result, "remux")
}

/// Counts reported by [`tk_package`].
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct TkPackageSummary {
    /// Number of packaged tracks.
    pub tracks: u32,
    /// Number of segments per track.
    pub segments: u32,
    /// Files written into the output directory.
    pub files: u64,
    /// Bytes of media written.
    pub bytes: u64,
}

/// Writes an HLS + DASH package of `input` into the directory `out_dir` (created if
/// missing). `segment_seconds` must be positive; segments cut on key frames.
///
/// Encryption is off when both `key_id` and `key` are null. Otherwise both are
/// 32-digit hex strings (16 bytes each) and `scheme` is `"cenc"` or `"cbcs"` (null
/// means `"cenc"`). `summary`, when not null, receives the counts. Returns 0 on
/// success and -1 on error.
///
/// # Safety
/// String arguments must be null or NUL-terminated UTF-8. `summary` must be null or
/// point to writable memory for a [`TkPackageSummary`].
#[no_mangle]
pub unsafe extern "C" fn tk_package(
    input: *const c_char,
    out_dir: *const c_char,
    segment_seconds: f64,
    key_id: *const c_char,
    key: *const c_char,
    scheme: *const c_char,
    summary: *mut TkPackageSummary,
) -> c_int {
    let result = catch_unwind(AssertUnwindSafe(|| -> Result<(), String> {
        let input = path_arg(input, "input").ok_or("input is missing")?;
        let out_dir = path_arg(out_dir, "out_dir").ok_or("out_dir is missing")?;
        let encryption = encryption_arg(key_id, key, scheme)?;
        let done = tpt_kinetix_ops::package::package(
            &input,
            Path::new(&out_dir),
            segment_seconds,
            encryption,
        )
        .map_err(|e| format!("{e:#}"))?;
        if !summary.is_null() {
            // SAFETY: the caller promised `summary` is writable for one struct.
            *summary = TkPackageSummary {
                tracks: done.tracks as u32,
                segments: done.segments as u32,
                files: done.files as u64,
                bytes: done.bytes,
            };
        }
        Ok(())
    }));
    status(result, "package")
}

/// Builds the optional CENC key from the three C arguments of [`tk_package`].
///
/// # Safety
/// Same contract as [`opt_arg`].
unsafe fn encryption_arg(
    key_id: *const c_char,
    key: *const c_char,
    scheme: *const c_char,
) -> Result<Option<Encryption>, String> {
    let key_id = opt_arg(key_id, "key_id")?;
    let key = opt_arg(key, "key")?;
    let scheme = opt_arg(scheme, "scheme")?.unwrap_or_else(|| "cenc".to_owned());
    tpt_kinetix_ops::encryption_from_hex(key_id.as_deref(), key.as_deref(), &scheme)
        .map_err(|e| format!("{e:#}"))
}

/// Maps a caught result to the C convention: 0 on success, -1 with the error stored.
fn status(result: std::thread::Result<Result<(), String>>, what: &str) -> c_int {
    match result {
        Ok(Ok(())) => 0,
        Ok(Err(e)) => {
            set_error(e);
            -1
        }
        Err(_) => {
            set_error(format!("internal error (panic) during {what}"));
            -1
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn null_and_missing_paths_fail_cleanly() {
        unsafe {
            assert!(tk_probe_json(std::ptr::null()).is_null());
            let msg = CStr::from_ptr(tk_last_error()).to_str().unwrap();
            assert!(msg.contains("null"));
            let missing = CString::new("/definitely/not/here.mp4").unwrap();
            assert!(tk_probe_json(missing.as_ptr()).is_null());
            let output = CString::new("/definitely/not/out.mp4").unwrap();
            assert_eq!(tk_faststart(missing.as_ptr(), output.as_ptr()), -1);
        }
    }

    #[test]
    fn version_is_a_static_c_string() {
        let v = unsafe { CStr::from_ptr(tk_version()) }.to_str().unwrap();
        assert_eq!(v, env!("CARGO_PKG_VERSION"));
    }
}
